{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "All observational studies (eg, cross-sectional, cohort, case-control studies, and case series) except for case reports were included. We included studies that reported the prevalence of COVID-19 in HCWs, using either reverse transcription-polymerase chain reaction (RT-PCR) or a serum antibodies assay. We also included studies evaluating the risk factors for SARS-CoV-2 infection and those analyzing the clinical characteristics and outcomes of laboratory-confirmed COVID-19 among HCWs. We excluded those articles that evaluated HCWs with suspected but not laboratory-confirmed SARS-CoV-2 infection.",
      "reason": "The manuscript specifies the eligible study designs (observational studies, excluding case reports), the population (HCWs), the outcomes/topics (prevalence, risk factors, clinical characteristics, outcomes), and the diagnostic criteria (RT-PCR or serum antibodies assay)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Medline, Embase, Latin American and Caribbean Health Sciences Literature (LILACS), Cochrane, Web of Science, the World Health Organization COVID-19 database, Google Scholar, and Living Evidence on COVID-19, a database developed by the Institute of Social and Preventive Medicine, University of Bern, were searched to identify relevant articles from inception until July 8, 2020, without language restrictions. ... We limited our search to human studies, with no language restriction.",
      "reason": "The manuscript specifies the search period (inception until July 8, 2020) and language restrictions (none)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; this is a conditional requirement that does not apply here."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Screening criteria, geographic location, HCW professions, the clinical setting, and the mean of daily new cases of SARS-CoV-2 per million inhabitants (15) in the country during the period in which the study was carried out were prespecified as characteristics for assessment of heterogeneity and were evaluated using stratified analyses and univariate random-effects meta-regression.",
      "reason": "The manuscript specifies the characteristics used for grouping studies in the synthesis (stratified analyses) to assess heterogeneity."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond standard systematic review inclusion/exclusion criteria."
    }
  ],
  "confidence": 100
}

