    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The choice of effect measure is standard for the types of data (prevalence/proportions and dichotomous risk factors) and does not require specific justification in this context."
